#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin>>n;
    vector<int> K(n);
    vector<vector<pair<int,int>>> orig(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>K[i]; orig[i].resize(K[i]);
        for(int j=0;j<K[i];j++) cin>>orig[i][j].first>>orig[i][j].second;
        totalCells+=K[i];
    }
    // Apply flip f first (if f=1, reflect x->-x), then rotate r times 90° CCW
    // CCW rotation: (x,y)->(−y,x)
    auto applyTransform=[](vector<pair<int,int>>& cells, int f, int r)->vector<pair<int,int>>{
        vector<pair<int,int>> res;
        for(auto [x,y]:cells){
            int nx=x,ny=y;
            if(f) nx=-nx;
            for(int q=0;q<r;q++){int t=nx;nx=-ny;ny=t;}
            res.push_back({nx,ny});
        }
        int mx=INT_MAX,my=INT_MAX;
        for(auto&[x,y]:res){mx=min(mx,x);my=min(my,y);}
        for(auto&[x,y]:res){x-=mx;y-=my;}
        return res;
    };
    struct Ori{vector<pair<int,int>>cells;int w,h,f,r;};
    vector<vector<Ori>> allO(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>>seen;
        for(int f=0;f<2;f++)for(int r=0;r<4;r++){
            auto tc=applyTransform(orig[i],f,r);
            sort(tc.begin(),tc.end());
            if(seen.insert(tc).second){
                int w=0,h=0;
                for(auto[x,y]:tc){w=max(w,x+1);h=max(h,y+1);}
                allO[i].push_back({tc,w,h,f,r});
            }
        }
    }
    vector<int> ord(n); iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int a,int b){return K[a]>K[b];});
    auto t0=chrono::steady_clock::now();
    auto elt=[&](){return chrono::duration<double>(chrono::steady_clock::now()-t0).count();};
    long long bestArea=LLONG_MAX; int bestW=0,bestH=0;
    struct Pl{int x,y,r,f;};
    vector<Pl> bestPl(n);
    int sq=(int)ceil(sqrt((double)totalCells));
    for(int W=max(1,sq/2);W<=sq*3+20&&elt()<9.0;W++){
        int mxH=min(4000000/max(1,W),totalCells/max(1,W)+200);
        if(mxH<1)continue;
        vector<int>hm(W,0);
        vector<vector<bool>>grid(W,vector<bool>(mxH,false));
        vector<Pl>pl(n); int curH=0; bool fail=false;
        for(int idx=0;idx<n&&!fail;idx++){
            if(elt()>9.5)break;
            int pi=ord[idx]; int bs=INT_MAX,bx=-1,by=-1,bo=-1;
            for(int oi=0;oi<(int)allO[pi].size();oi++){
                auto&o=allO[pi][oi]; if(o.w>W)continue;
                for(int x=0;x<=W-o.w;x++){
                    int my=0; for(auto[cx,cy]:o.cells)my=max(my,hm[x+cx]-cy);
                    if(my<0)my=0;
                    int top=0; for(auto[cx,cy]:o.cells)top=max(top,my+cy+1);
                    if(top>mxH)continue;
                    bool ok=true; for(auto[cx,cy]:o.cells)if(grid[x+cx][my+cy]){ok=false;break;}
                    if(ok){int sc=top*10000+x;if(sc<bs){bs=sc;bx=x;by=my;bo=oi;}}
                }
            }
            if(bx==-1){fail=true;break;}
            auto&o=allO[pi][bo];
            for(auto[cx,cy]:o.cells){grid[bx+cx][by+cy]=true;hm[bx+cx]=max(hm[bx+cx],by+cy+1);curH=max(curH,by+cy+1);}
            pl[pi]={bx,by,o.r,o.f};
        }
        if(fail)continue;
        long long area=(long long)W*curH;
        if(area<bestArea){bestArea=area;bestW=W;bestH=curH;bestPl=pl;}
    }
    if(bestArea==LLONG_MAX){
        bestW=totalCells;bestH=1;int cx=0;
        for(int i=0;i<n;i++){bestPl[i]={cx,0,0,0};cx+=allO[i][0].w;bestH=max(bestH,allO[i][0].h);}
        bestW=cx;
    }
    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
}
